-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다
-- (소식 표의 줄 수·텔레그램 줄 수·방 수·보관 찬 줄 수·표 권한·정책·칸 권한 해시 변화 없음).
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261027010000' and name='tg_room_day_group')=1 then '예' else '아니오' end as value
union all select 'three new tables: RLS on, one read policy each (authenticated, owner check)',case when (select count(*) from pg_class where oid in(to_regclass('public.app_feed_folders'),to_regclass('public.app_feed_rooms'),to_regclass('public.app_feed_room_days')) and relrowsecurity and not relforcerowsecurity and coalesce(relacl::text,'')!~'(^|[{,])(anon)?=')=3 and (select count(*) from pg_policy where polrelid in(to_regclass('public.app_feed_folders'),to_regclass('public.app_feed_rooms'),to_regclass('public.app_feed_room_days')) and polcmd='r' and polroles=array['authenticated'::regrole]::oid[] and pg_get_expr(polqual,polrelid) like '%app_is_workspace_owner%')=3 and (select count(*) from pg_policy where polrelid in(to_regclass('public.app_feed_folders'),to_regclass('public.app_feed_rooms'),to_regclass('public.app_feed_room_days')))=3 then '예' else '아니오' end
union all select 'new tables: authenticated reads only, service_role and anon nothing',case when has_table_privilege('authenticated','public.app_feed_folders','select') and has_table_privilege('authenticated','public.app_feed_rooms','select') and has_table_privilege('authenticated','public.app_feed_room_days','select') and not has_table_privilege('authenticated','public.app_feed_folders','insert') and not has_table_privilege('authenticated','public.app_feed_folders','update') and not has_table_privilege('authenticated','public.app_feed_folders','delete') and not has_table_privilege('authenticated','public.app_feed_rooms','insert') and not has_table_privilege('authenticated','public.app_feed_rooms','update') and not has_table_privilege('authenticated','public.app_feed_rooms','delete') and not has_table_privilege('authenticated','public.app_feed_room_days','insert') and not has_table_privilege('authenticated','public.app_feed_room_days','update') and not has_table_privilege('authenticated','public.app_feed_room_days','delete') and not has_any_column_privilege('service_role','public.app_feed_folders','select') and not has_any_column_privilege('service_role','public.app_feed_rooms','select') and not has_any_column_privilege('service_role','public.app_feed_room_days','select') and not has_any_column_privilege('anon','public.app_feed_folders','select') and not has_any_column_privilege('anon','public.app_feed_rooms','select') and not has_any_column_privilege('anon','public.app_feed_room_days','select') then '예' else '아니오' end
union all select 'eight definer functions: empty search_path, no anon or PUBLIC execute',case when (select count(*) from pg_proc p where p.oid in(to_regprocedure('private.app_feed_owner_workspace()'),to_regprocedure('public.app_feed_room_touch(uuid,text,text,text,text)'),to_regprocedure('public.app_feed_room_day_add(uuid,text,date,jsonb)'),to_regprocedure('public.app_feed_room_set(text,uuid,boolean)'),to_regprocedure('public.app_feed_room_day_set(text,date,text)'),to_regprocedure('public.app_feed_folder_create(text)'),to_regprocedure('public.app_feed_folder_rename(uuid,text)'),to_regprocedure('public.app_feed_folder_delete(uuid)')) and p.prosecdef and p.proconfig=array['search_path=""'] and not has_function_privilege('anon',p.oid,'execute') and coalesce(p.proacl::text,'')!~'(^|[{,])=')=8 then '예' else '아니오' end
union all select 'list function: invoker (not definer), empty search_path, no anon or PUBLIC execute',case when (select count(*) from pg_proc p where p.oid=to_regprocedure('public.app_feed_room_day_lines(date,date)') and not p.prosecdef and p.proconfig=array['search_path=""'] and not has_function_privilege('anon',p.oid,'execute') and coalesce(p.proacl::text,'')!~'(^|[{,])=')=1 then '예' else '아니오' end
union all select 'function execute: server service_role, screen authenticated, helper nobody',case when has_function_privilege('service_role','public.app_feed_room_touch(uuid,text,text,text,text)','execute') and has_function_privilege('service_role','public.app_feed_room_day_add(uuid,text,date,jsonb)','execute') and not has_function_privilege('authenticated','public.app_feed_room_touch(uuid,text,text,text,text)','execute') and not has_function_privilege('authenticated','public.app_feed_room_day_add(uuid,text,date,jsonb)','execute') and has_function_privilege('authenticated','public.app_feed_room_set(text,uuid,boolean)','execute') and has_function_privilege('authenticated','public.app_feed_room_day_set(text,date,text)','execute') and has_function_privilege('authenticated','public.app_feed_folder_create(text)','execute') and has_function_privilege('authenticated','public.app_feed_folder_rename(uuid,text)','execute') and has_function_privilege('authenticated','public.app_feed_folder_delete(uuid)','execute') and has_function_privilege('authenticated','public.app_feed_room_day_lines(date,date)','execute') and not has_function_privilege('service_role','public.app_feed_room_set(text,uuid,boolean)','execute') and not has_function_privilege('service_role','public.app_feed_room_day_set(text,date,text)','execute') and not has_function_privilege('service_role','public.app_feed_folder_create(text)','execute') and not has_function_privilege('service_role','public.app_feed_folder_rename(uuid,text)','execute') and not has_function_privilege('service_role','public.app_feed_folder_delete(uuid)','execute') and not has_function_privilege('service_role','public.app_feed_room_day_lines(date,date)','execute') and not has_function_privilege('authenticated','private.app_feed_owner_workspace()','execute') and not has_function_privilege('service_role','private.app_feed_owner_workspace()','execute') and not has_function_privilege('anon','private.app_feed_owner_workspace()','execute') then '예' else '아니오' end
union all select 'new tables start empty',case when not exists(select 1 from public.app_feed_folders) and not exists(select 1 from public.app_feed_rooms) and not exists(select 1 from public.app_feed_room_days) then '예' else '아니오' end
union all select 'telegram room-day index present on the feed table',case when (select count(*) from pg_index i where i.indrelid=to_regclass('public.app_feed_items') and i.indexrelid=to_regclass('public.app_feed_items_tg_room_day_idx') and i.indpred is not null)=1 then '예' else '아니오' end
union all select 'no anon or PUBLIC table or column privilege on the feed and new tables',case when not exists(select 1 from pg_class where oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_folders'),to_regclass('public.app_feed_rooms'),to_regclass('public.app_feed_room_days')) and coalesce(relacl::text,'')~'(^|[{,])(anon)?=') and not exists(select 1 from pg_attribute where attrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_folders'),to_regclass('public.app_feed_rooms'),to_regclass('public.app_feed_room_days')) and attacl::text~'(^|[{,])(anon)?=') then '예' else '아니오' end
union all select 'feed items rows',(select count(*)::text from public.app_feed_items)
union all select 'feed telegram rows',(select count(*)::text from public.app_feed_items where source='telegram')
union all select 'feed telegram rooms',(select count(distinct room_key)::text from public.app_feed_items where source='telegram')
union all select 'feed items archived rows',(select count(*)::text from public.app_feed_items where archived_at is not null)
union all select 'feed table grants policies hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid=to_regclass('public.app_feed_items')),'')
  ||coalesce((select string_agg(a.attname::text||':'||a.attacl::text,',' order by a.attname) from pg_attribute a where a.attrelid=to_regclass('public.app_feed_items') and a.attnum>0 and not a.attisdropped and a.attacl is not null),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid=to_regclass('public.app_feed_items')),''));
